import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import DeleteKiosk from "@/components/PresenceApp/PopUps/DeleteKiosk.vue";
import EditKiosk from "@/components/PresenceApp/PopUps/EditKiosk.vue";
import CreateKiosk from "@/components/PresenceApp/PopUps/CreateKiosk.vue";
import { stichh_kiosk_function, update_list_kiosk_priority_message } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import { useDisplay } from "vuetify/lib/framework.mjs";
export default {
  components: {
    SnackBar,
    CreateKiosk,
    EditKiosk,
    DeleteKiosk
  },
  data() {
    return {
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      kioskCreation: false,
      kioskEdition: false,
      loading: false,
      kioskDeletion: false,
      componentCheck: 0,
      headers: [{
        title: "Name",
        value: "kiosk_name",
        sortable: false,
        width: "25%"
      }, {
        title: "Unique Id",
        value: "kiosk_unique_id",
        sortable: false,
        width: "25%"
      }, {
        title: "Location",
        value: "location_name",
        sortable: false,
        width: "25%"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        width: "25%"
      }],
      height: 0,
      page: 1,
      currentPage: 1,
      totalItems: 0,
      itemsPerPage: 10,
      fixed: true,
      endmodal: false,
      tableData: [],
      kioskMessages: [],
      kioskitem: {},
      tableLoading: false,
      CurrentDate: new Date().toISOString().substr(0, 10),
      draggedField: null,
      draggedIndex: null,
      dragOverIndex: null
    };
  },
  created() {
    this.height = window.innerHeight - 305;
    this.kioskListing();
    this.kioskConfiguration();
  },
  computed: {
    pageCount() {
      if (this.tableData.length === 0) return 1;
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + start);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end + 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  methods: {
    async validate_data() {
      this.loading = true;
      this.kioskMessages.forEach(obj => {
        delete obj.isEditing;
      });
      this.kioskMessages = this.kioskMessages.map((item, index) => ({
        ...item,
        PRIORITY: index + 1
      }));
      let data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(update_list_kiosk_priority_message, {
          input: {
            action_type: "UPDATE",
            organization_id: data.organization.organization_id,
            kiosk_prorities: JSON.stringify(this.kioskMessages)
          }
        }));
        this.loading = false;
        let response = JSON.parse(result.data.update_list_kiosk_priority_message);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "Updated Successfully",
            timeout: 5000,
            Top: true
          };
          this.kioskConfiguration();
        } else {
          this.loading = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors && error.errors[0] && error.errors[0].message || error.message || "Something went wrong",
          timeout: 5000,
          Top: true
        };
      }
    },
    startEditing(item) {
      item.isEditing = true;
    },
    stopEditing(item) {
      if (!item.MESSAGE.trim()) {
        item.MESSAGE = "";
        return;
      }
      item.isEditing = false;
    },
    allowDrop(event) {
      event.preventDefault();
    },
    dragStart(field, index) {
      this.draggedField = index;
    },
    dragEnd(field, index) {
      this.draggedField = null;
      if (this.dragOverIndex !== null) {
        // Move the field to the new position in the kioskMessages array
        const item = this.kioskMessages[index];
        this.kioskMessages.splice(index, 1);
        this.kioskMessages.splice(this.dragOverIndex, 0, item);
      }
      this.dragOverIndex = null;
    },
    dragOver(index) {
      this.dragOverIndex = index;
    },
    drop(event) {
      event.preventDefault();
    },
    add_action() {
      this.componentCheck = 1;
      this.kioskCreation = true;
    },
    delete_kiosk(item) {
      this.componentCheck = 3;
      this.kioskitem = item;
      this.kioskDeletion = true;
    },
    edit_kiosk(item) {
      this.componentCheck = 2;
      this.kioskitem = item;
      this.kioskEdition = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.kioskCreation = false;
      this.kioskEdition = false;
      this.kioskDeletion = false;
      this.kioskListing();
    },
    async kioskListing() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(stichh_kiosk_function, {
          input: {
            action_type: "LIST_KIOSK"
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.stichh_kiosk_function);
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
          this.totalItems = this.tableData.length;
        } else {
          this.tableData = [];
          this.totalItems = 0;
        }
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors && error.errors[0] && error.errors[0].message || error.message || "Something went wrong",
          timeout: 5000,
          Top: true
        };
      }
    },
    async kioskConfiguration() {
      let data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(update_list_kiosk_priority_message, {
          input: {
            action_type: "LIST",
            organization_id: data.organization.organization_id
          }
        }));
        let response = JSON.parse(result.data.update_list_kiosk_priority_message);
        if (response.Status == "SUCCESS") {
          this.kioskMessages = response.data;
        } else {
          this.kioskMessages = [];
        }
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors && error.errors[0] && error.errors[0].message || error.message || "Something went wrong",
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
